{
  "pipeline_id": "gatk-variant-calling",
  "name": "GATK Germline Variant Calling",
  "description": "Complete GATK4 Best Practices pipeline for germline SNP and indel discovery from paired-end FASTQ files. Covers QC, adapter trimming, BWA-MEM alignment, SAMtools sorting, Picard duplicate marking, and GATK HaplotypeCaller. Returns an unannotated VCF: variant consequence annotation is a separate step, since ANNOVAR is licence-gated and not installed. Based on Broad Institute recommendations for human WES/WGS data.",
  "estimated_duration": "4-8 hours",
  "inputs": [
    {
      "name": "inputFastqR1",
      "type": "file",
      "required": true,
      "description": "Read 1 FASTQ file (.fastq.gz)"
    },
    {
      "name": "inputFastqR2",
      "type": "file",
      "required": true,
      "description": "Read 2 FASTQ file (.fastq.gz)"
    },
    {
      "name": "referenceGenome",
      "type": "string",
      "required": false,
      "default": "references/GRCh38/hg38.fa",
      "description": "Reference genome FASTA path in workspace"
    },
    {
      "name": "sampleName",
      "type": "string",
      "required": false,
      "default": "sample",
      "description": "Sample identifier used for output file naming"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "fastqc",
      "description": "Quality control of raw reads"
    },
    {
      "step": 2,
      "tool": "trimmomatic",
      "description": "Remove adapters and low-quality bases from paired-end reads",
      "after": [
        "step1_fastqc"
      ]
    },
    {
      "step": 3,
      "tool": "bwa",
      "description": "Align trimmed reads to reference genome with BWA-MEM",
      "after": [
        "step2_trim"
      ]
    },
    {
      "step": 4,
      "tool": "samtools",
      "description": "Sort BAM by coordinate",
      "after": [
        "step3_align"
      ]
    },
    {
      "step": 5,
      "tool": "picard",
      "description": "Mark PCR and optical duplicate reads",
      "after": [
        "step4_sort"
      ]
    },
    {
      "step": 6,
      "tool": "samtools",
      "description": "Index the deduplicated BAM file",
      "after": [
        "step5_markdup"
      ]
    },
    {
      "step": 7,
      "tool": "gatk",
      "description": "Call germline SNPs and indels with HaplotypeCaller",
      "after": [
        "step6_index"
      ]
    }
  ]
}

